using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json.Linq;
public static class BEORepair {
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying||!s.path.EndsWith("Level_B4_Circular.unity"))throw new Exception("Saved B4 edit required");string r=Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));var rows=JArray.Parse(File.ReadAllText(r+"/SourceAssets/B4_ExperimentOperations/access_repairs.json"));var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B4_")).transform.Find("B4_실험운용설비");foreach(var q in rows){var t=root.GetComponentsInChildren<Transform>().Single(x=>x.name==(string)q["name"]);if((bool)q["remove"]){UnityEngine.Object.DestroyImmediate(t.gameObject);continue;}var p=q["position"];t.localPosition=new Vector3((float)p[0],(float)p[1],(float)p[2]);t.localRotation=Quaternion.Euler(0,(float)q["yaw"],0);PrefabUtility.RecordPrefabInstancePropertyModifications(t);}Physics.SyncTransforms();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);return new{repaired=rows.Count};}
}
